result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "tmpl.py", "content": """"A small Jinja-flavored template engine subset (no jinja2 dependency).

Features:
  - {{ expr }} output with dotted lookup (dict + attribute access)
  - Filters: {{ name|upper }}, {{ items|length }}, {{ v|default('x') }}, |safe
  - {% if %} / {% elif %} / {% else %} / {% endif %}
  - {% for x in seq %} / {% endfor %} with loop.index (1-based) and loop.last
  - Auto HTML-escaping of output unless piped through |safe
  - TemplateError with line numbers for unclosed/mismatched tags
"""

from __future__ import annotations

import re
from html import escape as _html_escape


class TemplateError(Exception):
    def __init__(self, message: str, line: int | None = None):
        self.line = line
        super().__init__(message)


# ---------------------------------------------------------------- tokens

TOKEN_RE = re.compile(r"\{\{(.*?)\}\}|\{%(-?\s*(.*?)-?)\s*%\}", re.DOTALL)

TAG_RE = re.compile(r"^(if|elif|else|endif|for|endfor)\b\s*(.*)$", re.DOTALL)


def _tokenize(source: str):
    """Yield (kind, content, line) tuples. kind in {text, expr, tag}."""
    pos = 0
    line = 1
    for m in TOKEN_RE.finditer(source):
        text = source[pos:m.start()]
        yield ("text", text, line)
        line += text.count("\n")
        if m.group(0).startswith("{{"):
            if m.group(1) is None:
                raise TemplateError("Unclosed expression '{{' without '}}'", line)
            yield ("expr", m.group(1), line)
        else:
            inner = m.group(2)
            if inner is None:
                raise TemplateError("Unclosed statement '{%' without '%}'", line)
            tm = TAG_RE.match(inner.strip())
            if not tm:
                raise TemplateError(f"Unknown tag: {inner.strip()!r}", line)
            yield ("tag", (tm.group(1), tm.group(2).strip()), line)
        pos = m.end()
    yield ("text", source[pos:], line)


# ---------------------------------------------------------------- expressions

_IDENT = r"[A-Za-z_][A-Za-z0-9_]*"


class _Undefined:
    _inst = None

    def __new__(cls):
        if cls._inst is None:
            cls._inst = super().__new__(cls)
        return cls._inst

    def __bool__(self):
        return False

    def __str__(self):
        return ""

    def __repr__(self):
        return "undefined"


UNDEFINED = _Undefined()


class SafeString(str):
    """A string already deemed safe; autoescaping skips it."""


def _escape(value) -> str:
    if isinstance(value, SafeString):
        return str(value)
    return _html_escape(str(value), quote=True)


def _lookup(base, parts, line):
    cur = base
    for part in parts:
        if isinstance(cur, _Undefined):
            return UNDEFINED
        try:
            if isinstance(cur, dict):
                cur = cur[part] if part in cur else getattr(cur, part, UNDEFINED)
            else:
                cur = getattr(cur, part)
        except (KeyError, AttributeError, TypeError):
            return UNDEFINED
        if cur is None:
            continue
    return cur


class ExprParser:
    """Parses: literal | dotted-name | dotted-name(args) chained with |filters."""

    def __init__(self, text: str, line: int):
        self.tokens = re.findall(rf"{_IDENT}(?:\.{_IDENT})*|'(?:[^']*)'|\"(?:[^\"]*)\"|\d+(?:\.\d+)?|[|(),=<>!]", text)
        if "".join(self.tokens).replace(" ", "") != re.sub(r"\s+", "", text):
            # ensure we didn't silently drop characters
            stripped = re.sub(r"\s+", "", text)
            if "".join(self.tokens) != stripped:
                raise TemplateError(f"Could not parse expression: {text!r}", line)
        self.pos = 0
        self.line = line
        self.text = text

    def _next(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def _peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def parse(self):
        node = self.parse_primary()
        while self._peek() == "|":
            self._next()
            fname = self._next()
            if not re.fullmatch(_IDENT, fname):
                raise TemplateError(f"Bad filter name {fname!r} in {self.text!r}", self.line)
            args = []
            if self._peek() == "(":
                self._next()
                while True:
                    if self._peek() == ")":
                        self._next()
                        break
                    args.append(self.parse_arg())
                    if self._peek() == ",":
                        self._next()
                    elif self._peek() == ")":
                        self._next()
                        break
                    elif self._peek() is None:
                        raise TemplateError(f"Unterminated argument list in {self.text!r}", self.line)
                    else:
                        raise TemplateError(f"Expected ',' or ')' in {self.text!r}", self.line)
            node = ("filter", fname, [node] + args)
        if self._peek() is not None:
            raise TemplateError(f"Unexpected token {self._peek()!r} in {self.text!r}", self.line)
        return node

    def parse_arg(self):
        tok = self._peek()
        if tok is None:
            raise TemplateError(f"Missing argument in {self.text!r}", self.line)
        if tok.startswith(("'", '"')):
            self._next()
            return ("const", tok[1:-1])
        if re.fullmatch(r"\d+(?:\.\d+)?", tok):
            self._next()
            return ("const", float(tok) if "." in tok else int(tok))
        return self.parse_name_node()

    def parse_primary(self):
        tok = self._peek()
        if tok is None:
            raise TemplateError(f"Empty expression", self.line)
        if tok in ("true", "True"):
            self._next()
            return ("const", True)
        if tok in ("false", "False"):
            self._next()
            return ("const", False)
        if tok in ("none", "None"):
            self._next()
            return ("const", None)
        if tok.startswith(("'", '"')):
            self._next()
            return ("const", tok[1:-1])
        if re.fullmatch(r"\d+(?:\.\d+)?", tok):
            self._next()
            return ("const", float(tok) if "." in tok else int(tok))
        return self.parse_name_node()

    def parse_name_node(self):
        tok = self._next()
        if not re.fullmatch(_IDENT + r"(?:\." + _IDENT + r")*", tok):
            raise TemplateError(f"Expected a name in {self.text!r}, got {tok!r}", self.line)
        return ("lookup", tok.split("."))


FILTERS = {
    "upper": lambda v: str(v).upper(),
    "lower": lambda v: str(v).lower(),
    "title": lambda v: str(v).title(),
    "trim": lambda v: str(v).strip(),
    "capitalize": lambda v: str(v).capitalize(),
    "length": lambda v: len(v),
    "count": lambda v: len(v),
    "safe": lambda v: v if isinstance(v, SafeString) else SafeString(str(v)),
    "default": lambda v, d="": d if isinstance(v, _Undefined) or v is None or v == "" else v,
    "join": lambda v, sep="": str(sep).join(str(x) for x in v),
    "first": lambda v: v[0] if v else UNDEFINED,
    "last": lambda v: v[-1] if v else UNDEFINED,
    "int": lambda v: int(v),
    "striptags": lambda v: re.sub(r"<[^>]*>", "", str(v)),
}


def _apply_filter(name, args, line):
    fn = FILTERS.get(name)
    if fn is None:
        raise TemplateError(f"Unknown filter {name!r}", line)
    try:
        return fn(*args)
    except TemplateError:
        raise
    except Exception as exc:
        raise TemplateError(f"Filter {name!r} failed: {exc}", line)


def _eval(node, scopes, line):
    kind = node[0]
    if kind == "const":
        return node[1]
    if kind == "lookup":
        parts = node[1]
        for scope in reversed(scopes):
            if parts[0] in scope:
                return _lookup(scope[parts[0]], parts[1:], line)
        return UNDEFINED
    if kind == "filter":
        name = node[1]
        values = [_eval(a, scopes, line) for a in node[2]]
        out = _apply_filter(name, values, line)
        # |safe must survive subsequent non-mutating chaining; upper/lower/etc
        # produce plain strings that need escaping again only if they came from
        # unsafe data -- but jinja marks filtered output escaped-safe. We keep
        # SafeString sticky through string filters for simplicity.
        return out
    raise TemplateError(f"Cannot evaluate node {node!r}", line)


# ---------------------------------------------------------------- parsing

TEXT, OUTPUT, IF, ELIF, ELSE, ENDIF, FOR, ENDFOR = range(8)


class _Node:
    __slots__ = ("kind", "data", "children", "line")

    def __init__(self, kind, data=None, children=None, line=None):
        self.kind = kind
        self.data = data
        self.children = children or []
        self.line = line


class _Parser:
    def __init__(self, source: str):
        self.tokens = list(_tokenize(source))
        self.pos = 0

    def _peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _advance(self):
        tok = self._peek()
        self.pos += 1
        return tok

    def parse(self):
        nodes, closer = self._parse_block(())
        if closer is not None:
            kind, line = closer
            raise TemplateError(f"Unexpected {{{% {kind} %}}} without matching opening tag", line)
        return nodes

    def _parse_block(self, terminators):
        """Parse until a tag whose name is in `terminators`.

        Returns (nodes, closer) where closer is (tagname, line) or None at EOF.
        """
        nodes = []
        while True:
            tok = self._peek()
            if tok is None:
                return nodes, None
            kind, content, line = self._advance()
            if kind == "text":
                if content:
                    nodes.append(_Node(TEXT, data=content))
            elif kind == "expr":
                ast = ExprParser(content.strip(), line).parse()
                uses_safe = self._uses_safe(ast)
                nodes.append(_Node(OUTPUT, data=(ast, uses_safe), line=line))
            else:
                tagname, arg = content
                if tagname in terminators:
                    self.pos -= 1  # let caller consume it
                    return nodes, (tagname, line)
                if tagname == "if":
                    nodes.append(self._parse_if(arg, line))
                elif tagname == "for":
                    nodes.append(self._parse_for(arg, line))
                elif tagname in ("elif", "else", "endif"):
                    raise TemplateError(
                        f"Unexpected {{{% {tagname} %}}} without matching {{% if %}}", line
                    )
                elif tagname == "endfor":
                    raise TemplateError(
                        f"Unexpected {{{% endfor %}}} without matching {{% for %}}", line
                    )
                else:  # pragma: no cover
                    raise TemplateError(f"Unknown tag {tagname!r}", line)

    @staticmethod
    def _uses_safe(node):
        if node[0] == "filter":
            if node[1] == "safe":
                return True
            return any(Parser._uses_safe(a) for a in node[2])
        return False

    def _parse_if(self, cond_text, line):
        if not cond_text.strip():
            raise TemplateError("{% if %} requires a condition", line)
        branches = []
        cond_ast = ExprParser(cond_text.strip(), line).parse()
        body, closer = self._parse_block(("elif", "else", "endif"))
        branches.append((cond_ast, body))
        while closer and closer[0] == "elif":
            eline = closer[1]
            _, content, _ = self._advance()
            _, arg = content
            if not arg.strip():
                raise TemplateError("{% elif %} requires a condition", eline)
            body, closer = self._parse_block(("elif", "else", "endif"))
            branches.append((ExprParser(arg.strip(), eline).parse(), body))
        else_body = []
        if closer and closer[0] == "else":
            eline = closer[1]
            self._advance()
            else_body, closer = self._parse_block(("endif",))
            if not closer:
                raise TemplateError(
                    f"Unclosed tag: '{{% if {cond_text.strip()} %}}' on line {line} "
                    f"is never closed with {{% endif %}}",
                    line,
                )
        if not closer or closer[0] != "endif":
            raise TemplateError(
                f"Unclosed tag: '{{% if {cond_text.strip()} %}}' on line {line} "
                f"is never closed with {{% endif %}}",
                line,
            )
        self._advance()  # consume endif
        return _Node(IF, data=(branches, else_body), line=line)

    def _parse_for(self, arg, line):
        m = re.fullmatch(rf"({_IDENT})\s+in\s+(.+)", arg.strip(), re.DOTALL)
        if not m:
            raise TemplateError(f"Malformed for tag: '{{% for {arg} %}}'", line)
        var, iter_text = m.group(1), m.group(2).strip()
        iter_ast = ExprParser(iter_text, line).parse()
        body, closer = self._parse_block(("endfor",))
        if not closer:
            raise TemplateError(
                f"Unclosed tag: '{{% for {var} in {iter_text} %}}' on line {line} "
                f"is never closed with {{% endfor %}}",
                line,
            )
        self._advance()  # consume endfor
        return _Node(FOR, data=(var, iter_ast), children=body, line=line)


# ---------------------------------------------------------------- rendering


def _render_nodes(nodes, scopes, out):
    for node in nodes:
        if node.kind == TEXT:
            out.append(node.data)
        elif node.kind == OUTPUT:
            ast, uses_safe = node.data
            value = _eval(ast, scopes, node.line)
            if value is UNDEFINED:
                value = ""
            if uses_safe:
                out.append(SafeString(value) if not isinstance(value, SafeString) else value)
            else:
                out.append(_escape(value))
        elif node.kind == IF:
            branches, else_body = node.data
            for cond, body in branches:
                if _truthy(_eval(cond, scopes, node.line)):
                    _render_nodes(body, scopes, out)
                    break
            else:
                _render_nodes(else_body, scopes, out)
        elif node.kind == FOR:
            var, iter_ast = node.data
            iterable = _eval(iter_ast, scopes, node.line)
            if iterable is UNDEFINED:
                continue
            seq = list(iterable)
            n = len(seq)
            for i, item in enumerate(seq):
                scopes.append({var: item, "loop": {"index": i + 1, "index0": i, "last": i == n - 1}})
                try:
                    _render_nodes(node.children, scopes, out)
                finally:
                    scopes.pop()
        else:  # pragma: no cover
            raise TemplateError(f"Unknown node {node.kind!r}", node.line)


def _truthy(value):
    return bool(value)


def render(template: str, context: dict | None = None) -> str:
    """Render `template` with `context`. See module docstring for features."""
    ast = _Parser(template).parse()
    out: list[str] = []
    _render_nodes(ast, [dict(context or {})], out)
    return "".join(out)
